// ❌ ANTES — God class con múltiples responsabilidades
public class PlayerGod : MonoBehaviour
{
    void Update()
    {
        HandleInput();   // responsabilidad 1: input
        ApplyPhysics();  // responsabilidad 2: física
        UpdateHUD();     // responsabilidad 3: UI
        PlaySounds();    // responsabilidad 4: audio
        SaveProgress();  // responsabilidad 5: persistencia
    }
}

// ✅ DESPUÉS — cada clase tiene una sola responsabilidad
public class PlayerInputHandler : MonoBehaviour { ... }  // solo input
public class PlayerMovement    : MonoBehaviour { ... }  // solo física/movimiento
public class PlayerHUD         : MonoBehaviour { ... }  // solo UI
public class PlayerAudio       : MonoBehaviour { ... }  // solo audio
public class PlayerSaveSystem  : MonoBehaviour { ... }  // solo persistencia

